"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[3620],{21894:e=>{e.exports=JSON.parse('{"product":"Actions & Events","entries":[{"id":"2026-08-26-streaming-migration-messaging-updated","date":"2026-08-26","products":["Actions & Events"],"product":"Actions & Events","channel":"","changeType":"Changed","title":"Event Streaming migration guidance updated for general availability","excerpt":"The Event Streaming migration guide and overview no longer describe moving off the legacy Streaming API (SAPI) as optional. Existing customers are automatically migrated to the Pulsar-based Event Streaming service on a rolling schedule, with advance notice sent ahead of each migration.","hasArticle":true},{"id":"2026-08-10-event-field-json-types-not-fixed","date":"2026-08-10","products":["Actions & Events"],"product":"Actions & Events","channel":"","changeType":"Fixed","title":"Event Streaming field reference corrected: JSON types are not fixed per field","excerpt":"The Event Streaming field reference previously said boolean values in events \\"are represented as strings... rather than native JSON booleans\\" \u2014 a claim its own example immediately contradicted by showing both a quoted and an unquoted boolean value in the same payload. The section has been corrected and expanded to desc\u2026","hasArticle":true},{"id":"2026-08-10-interaction-event-timestamp-corrected","date":"2026-08-10","products":["Actions & Events"],"product":"Actions & Events","channel":"","changeType":"Fixed","title":"Event Streaming timestamp field corrected: use interactionEventTS for event time","excerpt":"The Event Streaming field and event reference docs previously told integrators to use eventTS to calculate durations between lifecycle events \u2014 queue time, ring time, talk time, and wrap-up time. That was incorrect: eventTS is the time the interaction was first offered (queue entry), and it carries the identical value\u2026","hasArticle":true},{"id":"2026-08-04-bridge-adapter-endpoint-for-sapi-migration","date":"2026-08-04","products":["Actions & Events"],"product":"Actions & Events","channel":"Streaming","changeType":"Added","title":"Bridge adapter endpoint for SAPI migration","excerpt":"The Streaming API migration guide now documents a backwards-compatible adapter (Bridge) endpoint \u2014 a second migration path for existing Streaming API integrations that cannot move to the Pulsar API directly.","hasArticle":true},{"id":"2026-07-30-webchat-content-security-policy-guide","date":"2026-07-30","products":["Actions & Events"],"product":"Actions & Events","channel":"WebChat","changeType":"Added","title":"WebChat Content-Security-Policy guide","excerpt":"Embedding the 8x8 WebChat v2 widget behind a strict Content-Security-Policy meant guessing which directives to allow. A new Content Security Policy guide documents exactly what your embedding page\'s CSP needs.","hasArticle":true}]}')}}]);